"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { glowControlChecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Firefly Switch: a 2.5rem by 1.5rem warm track with a white knob on a soft
 * three-layer shadow. On, the track lights up in the primary button's
 * material and the knob slides a full knob-width.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "peer inline-flex h-6 w-10 shrink-0 cursor-pointer items-center rounded-full border border-transparent bg-(--surface-3) p-0.5",
        "transition-[background-color,box-shadow] duration-fast ease-out",
        "hover:data-[unchecked]:bg-(--line-strong)",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary",
        glowControlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-4 rounded-full bg-(--thumb) shadow-(--shadow-thumb)",
          "transition-transform duration-fast ease-out",
          "data-[checked]:translate-x-4.5 data-[unchecked]:translate-x-0",
          "data-[disabled]:bg-muted data-[disabled]:shadow-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
